custom_css:
.sc-tw :root{
      color-scheme: dark;
      --slate: oklch(18% 0.02 240);
      --slate-2: oklch(14% 0.018 240);
      --ochre: oklch(74% 0.12 68);
      --ochre-deep: oklch(56% 0.08 62);
      --oak: oklch(82% 0.08 90);
      --ink: oklch(96% 0.01 240);
      --muted: rgba(255, 255, 255, .66);
      --leaf: oklch(61% 0.12 145);
      --petal: oklch(80% 0.11 1);
    }.sc-tw *{
      box-sizing: border-box;
    }.sc-tw html{
      scroll-behavior: smooth;
    }.sc-tw{
      margin: 0;
      overflow-x: hidden;
      font-family: 'Inter Tight', sans-serif;
      background:
        radial-gradient(circle at 12% 10%, rgba(196, 145, 62, .14), transparent 18%),
        radial-gradient(circle at 84% 16%, rgba(255, 255, 255, .05), transparent 18%),
        linear-gradient(180deg, oklch(18% 0.02 240) 0%, oklch(15% 0.018 240) 55%, oklch(12% 0.016 240) 100%);
      color: white;
    }.sc-tw body::before{
      content: '';
      position: fixed;
      inset: 0;
      pointer-events: none;
      background-image:
        linear-gradient(rgba(255, 255, 255, .035) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, .035) 1px, transparent 1px),
        linear-gradient(135deg, transparent 0 48%, rgba(255, 255, 255, .02) 48% 52%, transparent 52%),
        linear-gradient(45deg, transparent 0 48%, rgba(255, 255, 255, .02) 48% 52%, transparent 52%);
      background-size: 120px 120px, 120px 120px, 280px 280px, 280px 280px;
      opacity: .22;
      z-index: -2;
    }.sc-tw .serif{
      font-family: 'Cormorant Garamond', serif;
      letter-spacing: -0.055em;
    }.sc-tw .copy{
      font-family: 'Inter Tight', sans-serif;
    }.sc-tw .material-panel{
      background: linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, .03));
      border: 1px solid rgba(255, 255, 255, .08);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .08),
        0 24px 80px rgba(0, 0, 0, .35);
      backdrop-filter: blur(20px) contrast(.98);
      -webkit-backdrop-filter: blur(20px) contrast(.98);
    }.sc-tw .smoked-glass{
      background: rgba(255, 255, 255, .07);
      backdrop-filter: blur(15px) contrast(.95);
      -webkit-backdrop-filter: blur(15px) contrast(.95);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .1),
        0 20px 60px rgba(0, 0, 0, .28);
    }.sc-tw .textural-touch{
      position: relative;
      overflow: hidden;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, .78), rgba(255, 255, 255, .52)),
        linear-gradient(135deg, rgba(0, 0, 0, .04), transparent 45%);
      border: 1px solid rgba(255, 255, 255, .18);
      color: #2b2319;
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .68),
        inset 0 -12px 16px rgba(125, 90, 40, .08),
        0 20px 40px rgba(0, 0, 0, .25);
      transition: transform .5s cubic-bezier(.16, 1, .3, 1), box-shadow .5s ease, background .4s ease;
    }.sc-tw .textural-touch::before{
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(135deg, rgba(0, 0, 0, .08) 0 1px, transparent 1px 100%),
        linear-gradient(45deg, rgba(0, 0, 0, .05) 0 1px, transparent 1px 100%);
      opacity: .2;
      mix-blend-mode: multiply;
      pointer-events: none;
    }.sc-tw .textural-touch::after{
      content: '';
      position: absolute;
      inset: -120%;
      background: linear-gradient(120deg, transparent 44%, rgba(255, 255, 255, .7) 50%, transparent 56%);
      transform: translateX(-140%) rotate(12deg);
      animation: sheen 9s ease-in-out infinite;
      pointer-events: none;
      mix-blend-mode: screen;
    }.sc-tw .textural-touch:hover{
      transform: translateY(-4px);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .74),
        inset 0 -12px 16px rgba(125, 90, 40, .1),
        0 28px 50px rgba(0, 0, 0, .28);
    }.sc-tw .textural-touch:active{
      transform: translateY(1px) scale(.99);
    }.sc-tw .slat-portal{
      position: absolute;
      inset: 0;
      overflow: hidden;
      mask-image: linear-gradient(90deg, black 0 100%);
      -webkit-mask-image: linear-gradient(90deg, black 0 100%);
    }.sc-tw .slat-portal::before{
      content: '';
      position: absolute;
      inset: 0;
      background:
        linear-gradient(180deg, rgba(0, 0, 0, .06), rgba(0, 0, 0, .38)),
        radial-gradient(circle at 50% 30%, rgba(255, 195, 120, .16), transparent 22%);
      z-index: 2;
      pointer-events: none;
    }.sc-tw .slat-mask::after{
      content: '';
      position: absolute;
      inset: 0;
      background:
        linear-gradient(180deg, rgba(18, 18, 20, .1), rgba(18, 18, 20, .26)),
        radial-gradient(circle at center, transparent 35%, rgba(0, 0, 0, .38) 100%);
      pointer-events: none;
    }.sc-tw .hero-video{
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      transform: scale(1.08);
      filter: saturate(1.08) contrast(1.05) brightness(.86);
      will-change: transform;
    }.sc-tw .hero{
      position: relative;
      min-height: 100svh;
      overflow: hidden;
      background: var(--slate);
    }.sc-tw .hero-copy{
      backdrop-filter: blur(15px) contrast(.95);
      -webkit-backdrop-filter: blur(15px) contrast(.95);
      background: rgba(17, 17, 19, .36);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .08),
        0 30px 80px rgba(0, 0, 0, .35);
      border: 1px solid rgba(255, 255, 255, .08);
    }.sc-tw .condense{
      opacity: 0;
      filter: blur(18px);
      transform: translateY(24px);
      animation: condense 1.2s cubic-bezier(.16, 1, .3, 1) forwards;
    }.sc-tw .condense:nth-child(2){
      animation-delay: .14s;
    }.sc-tw .condense:nth-child(3){
      animation-delay: .26s;
    }.sc-tw .condense:nth-child(4){
      animation-delay: .38s;
    }.sc-tw .header-rail{
      position: fixed;
      left: 20px;
      top: 20px;
      bottom: 20px;
      z-index: 70;
      width: 88px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 18px 14px;
      background: rgba(20, 20, 22, .46);
      backdrop-filter: blur(24px) contrast(.98);
      -webkit-backdrop-filter: blur(24px) contrast(.98);
      border: 1px solid rgba(255, 255, 255, .08);
      box-shadow: 0 20px 60px rgba(0, 0, 0, .28);
    }.sc-tw .rail-brand{
      writing-mode: vertical-rl;
      transform: rotate(180deg);
      text-transform: uppercase;
      letter-spacing: .34em;
      font-size: 10px;
      color: rgba(255, 255, 255, .68);
      align-self: center;
    }.sc-tw .rail-nav{
      display: flex;
      flex-direction: column;
      gap: 18px;
      align-items: center;
    }.sc-tw .rail-nav a{
      writing-mode: vertical-rl;
      transform: rotate(180deg);
      text-decoration: none;
      text-transform: uppercase;
      letter-spacing: .22em;
      font-size: 10px;
      color: rgba(255, 255, 255, .58);
      transition: .3s ease;
    }.sc-tw .rail-nav a:hover{
      color: rgba(255, 214, 146, .92);
    }.sc-tw .rail-mark{
      width: 100%;
      aspect-ratio: 1;
      display: grid;
      place-items: center;
      background: rgba(255, 255, 255, .06);
      border: 1px solid rgba(255, 255, 255, .08);
    }.sc-tw .top-meter{
      position: fixed;
      right: 24px;
      top: 20px;
      z-index: 70;
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 14px 18px;
      background: rgba(20, 20, 22, .46);
      backdrop-filter: blur(24px) contrast(.98);
      -webkit-backdrop-filter: blur(24px) contrast(.98);
      border: 1px solid rgba(255, 255, 255, .08);
      box-shadow: 0 18px 50px rgba(0, 0, 0, .22);
    }.sc-tw .meter-bar{
      width: 180px;
      height: 8px;
      background: rgba(255, 255, 255, .1);
      overflow: hidden;
    }.sc-tw .meter-bar span{
      display: block;
      height: 100%;
      width: 68%;
      background: linear-gradient(90deg, rgba(214, 154, 76, .8), rgba(255, 223, 180, .95));
    }.sc-tw .hero-main{
      position: relative;
      z-index: 4;
      min-height: 100svh;
      display: grid;
      place-items: center;
      padding: 120px 24px 48px 140px;
      text-align: center;
    }.sc-tw .hero-inner{
      max-width: 980px;
    }.sc-tw .eyebrow{
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 10px 16px;
      border-radius: 999px;
      background: rgba(255, 255, 255, .12);
      color: white;
      text-transform: uppercase;
      letter-spacing: .28em;
      font-size: 10px;
      backdrop-filter: blur(15px) contrast(.95);
      border: 1px solid rgba(255, 255, 255, .08);
    }.sc-tw .eyebrow span{
      width: 8px;
      height: 8px;
      background: var(--ochre);
      display: inline-block;
    }.sc-tw .title{
      margin-top: 22px;
      font-size: clamp(4.8rem, 12vw, 10.6rem);
      line-height: .82;
      letter-spacing: -.08em;
      color: white;
      text-shadow: 0 16px 38px rgba(0, 0, 0, .3);
    }.sc-tw .slat{
      display: inline-block;
      animation: slatIn 1.2s cubic-bezier(.16, 1, .3, 1) forwards;
      opacity: 0;
      transform: translateY(42px);
    }.sc-tw .slat:nth-child(2){
      animation-delay: .16s;
    }.sc-tw .slat:nth-child(3){
      animation-delay: .3s;
    }.sc-tw .hero-text{
      margin: 28px auto 0;
      max-width: 720px;
      font-size: 18px;
      line-height: 1.9;
      color: rgba(255, 255, 255, .82);
      padding: 20px 24px;
      border-radius: 1.5rem;
      background: rgba(255, 255, 255, .06);
      border: 1px solid rgba(255, 255, 255, .08);
      backdrop-filter: blur(15px) contrast(.95);
    }.sc-tw .hero-actions{
      display: flex;
      gap: 14px;
      justify-content: center;
      flex-wrap: wrap;
      margin-top: 34px;
    }.sc-tw .btn-a{
      height: 56px;
      padding-inline: 30px;
      cursor: pointer;
      border: none;
      color: #2c2317;
      font-size: 10px;
      letter-spacing: .26em;
      text-transform: uppercase;
    }.sc-tw .btn-b{
      height: 56px;
      padding-inline: 30px;
      cursor: pointer;
      font-size: 10px;
      letter-spacing: .26em;
      text-transform: uppercase;
      color: white;
      background: rgba(255, 255, 255, .06);
      border: 1px solid rgba(255, 255, 255, .12);
      backdrop-filter: blur(15px) contrast(.95);
    }.sc-tw .panel-space{
      padding: 120px 0;
    }.sc-tw .shell{
      width: min(1480px, calc(100% - 48px));
      margin: 0 auto;
    }.sc-tw .sofa-split{
      display: grid;
      grid-template-columns: 1.25fr .75fr;
      min-height: 760px;
      background: linear-gradient(180deg, rgba(255, 255, 255, .04), rgba(255, 255, 255, .02));
      box-shadow: 0 24px 70px rgba(0, 0, 0, .18);
      overflow: hidden;
    }.sc-tw .ochre-block{
      background:
        linear-gradient(180deg, rgba(215, 160, 84, .92), rgba(180, 125, 61, .88)),
        linear-gradient(135deg, rgba(255, 255, 255, .16), transparent 45%);
      position: relative;
    }.sc-tw .charcoal-block{
      background:
        linear-gradient(180deg, rgba(16, 16, 18, .96), rgba(28, 28, 31, .92)),
        linear-gradient(135deg, rgba(255, 255, 255, .06), transparent 45%);
      position: relative;
    }.sc-tw .sofa-copy{
      position: relative;
      z-index: 2;
      padding: 76px;
      display: flex;
      flex-direction: column;
      justify-content: center;
      background:
        linear-gradient(90deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, .02));
      backdrop-filter: blur(10px);
    }.sc-tw .sofa-copy h2,.sc-tw .module-head h2,.sc-tw .botanical h2{
      font-size: clamp(2.8rem, 5.5vw, 6rem);
      line-height: .9;
      letter-spacing: -.06em;
      color: white;
    }.sc-tw .sofa-copy p{
      margin-top: 22px;
      max-width: 640px;
      color: rgba(255, 255, 255, .86);
      line-height: 2;
      font-size: 16px;
    }.sc-tw .sofa-label{
      text-transform: uppercase;
      letter-spacing: .3em;
      font-size: 10px;
      color: rgba(255, 255, 255, .7);
    }.sc-tw .sofa-meta{
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 28px;
    }.sc-tw .sofa-meta span{
      padding: 12px 16px;
      background: rgba(255, 255, 255, .1);
      border: 1px solid rgba(255, 255, 255, .08);
      font-size: 10px;
      letter-spacing: .2em;
      text-transform: uppercase;
    }.sc-tw .accent-pane{
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 52px;
      color: white;
    }.sc-tw .accent-pane .small{
      text-transform: uppercase;
      letter-spacing: .28em;
      font-size: 10px;
      color: rgba(255, 255, 255, .72);
    }.sc-tw .accent-pane .value{
      font-size: clamp(3rem, 7vw, 6rem);
      line-height: .88;
      letter-spacing: -.06em;
      margin-top: 16px;
    }.sc-tw .accessory{
      padding: 120px 0;
    }.sc-tw .accessory-head{
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 28px;
    }.sc-tw .accessory-head p{
      max-width: 440px;
      color: rgba(255, 255, 255, .66);
      line-height: 1.9;
    }.sc-tw .shelf-grid{
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 18px;
    }.sc-tw .shelf{
      grid-column: span 4;
      min-height: 260px;
      padding: 26px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .03)),
        linear-gradient(135deg, rgba(255, 255, 255, .04), transparent 60%);
      border: 1px solid rgba(255, 255, 255, .08);
      box-shadow: 0 16px 40px rgba(0, 0, 0, .2);
      overflow: hidden;
      position: relative;
      opacity: 0;
      transform: translateY(28px);
      transition: opacity .7s ease, transform .7s cubic-bezier(.16, 1, .3, 1), box-shadow .4s ease;
    }.sc-tw .shelf::before{
      content: '';
      position: absolute;
      inset: 0;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, .05), transparent 20%),
        repeating-linear-gradient(90deg, rgba(255, 255, 255, .06) 0 1px, transparent 1px 28px);
      opacity: .2;
      pointer-events: none;
      mix-blend-mode: screen;
    }.sc-tw .shelf.revealed{
      opacity: 1;
      transform: translateY(0);
    }.sc-tw .shelf.tall{
      min-height: 360px;
    }.sc-tw .shelf.wide{
      grid-column: span 8;
    }.sc-tw .shelf .tag{
      text-transform: uppercase;
      letter-spacing: .28em;
      font-size: 10px;
      color: rgba(255, 255, 255, .58);
    }.sc-tw .shelf h3{
      margin-top: 18px;
      font-size: clamp(1.7rem, 3vw, 3rem);
      line-height: .95;
      letter-spacing: -.05em;
      color: white;
    }.sc-tw .shelf p{
      margin-top: 16px;
      max-width: 42ch;
      color: rgba(255, 255, 255, .72);
      line-height: 1.85;
    }.sc-tw .shelf .number{
      position: absolute;
      right: 22px;
      bottom: 18px;
      font-size: 64px;
      line-height: 1;
      color: rgba(255, 255, 255, .08);
      letter-spacing: -.08em;
    }.sc-tw .botanical{
      padding: 120px 0;
    }.sc-tw .botanical-shell{
      width: min(1480px, calc(100% - 48px));
      margin: 0 auto;
      padding: 56px;
      background:
        linear-gradient(180deg, rgba(14, 58, 37, .96), rgba(11, 31, 22, .98)),
        radial-gradient(circle at 20% 20%, rgba(92, 188, 99, .18), transparent 18%),
        radial-gradient(circle at 80% 30%, rgba(255, 168, 183, .18), transparent 18%);
      box-shadow: 0 28px 80px rgba(0, 0, 0, .25);
      position: relative;
      overflow: hidden;
    }.sc-tw .botanical-shell::before{
      content: '';
      position: absolute;
      inset: 0;
      background:
        linear-gradient(135deg, rgba(255, 255, 255, .04) 0 1px, transparent 1px 100%),
        linear-gradient(45deg, rgba(255, 255, 255, .03) 0 1px, transparent 1px 100%);
      opacity: .18;
      pointer-events: none;
    }.sc-tw .botanical-head{
      max-width: 820px;
      position: relative;
      z-index: 1;
    }.sc-tw .botanical-head .label{
      text-transform: uppercase;
      letter-spacing: .3em;
      font-size: 10px;
      color: rgba(255, 255, 255, .58);
    }.sc-tw .botanical-head h2{
      margin-top: 18px;
      font-size: clamp(2.8rem, 6vw, 6rem);
      line-height: .92;
      letter-spacing: -.06em;
      color: white;
    }.sc-tw .botanical-head p{
      margin-top: 20px;
      max-width: 720px;
      color: rgba(255, 255, 255, .74);
      line-height: 1.95;
      font-size: 16px;
    }.sc-tw .contrast-band{
      margin-top: 40px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 18px;
      position: relative;
      z-index: 1;
    }.sc-tw .plant-card{
      min-height: 240px;
      padding: 28px;
      border-radius: 28px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, .03));
      border: 1px solid rgba(255, 255, 255, .08);
      backdrop-filter: blur(18px);
      box-shadow: 0 18px 45px rgba(0, 0, 0, .22);
    }.sc-tw .plant-card h3{
      margin-top: 16px;
      font-size: clamp(2rem, 3vw, 3.5rem);
      line-height: .92;
      letter-spacing: -.05em;
      color: white;
    }.sc-tw .plant-card p{
      margin-top: 16px;
      line-height: 1.85;
      color: rgba(255, 255, 255, .72);
    }.sc-tw .foot{
      padding: 84px 0 110px;
    }.sc-tw .foot-shell{
      width: min(1480px, calc(100% - 48px));
      margin: 0 auto;
      padding: 44px 46px;
      background:
        linear-gradient(180deg, rgba(18, 18, 20, .98), rgba(10, 10, 12, .98));
      border: 1px solid rgba(255, 255, 255, .06);
      box-shadow: 0 24px 70px rgba(0, 0, 0, .24);
    }.sc-tw .foot-grid{
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 24px;
      align-items: end;
    }.sc-tw .foot-title{
      font-size: clamp(2.8rem, 5vw, 5rem);
      line-height: .92;
      letter-spacing: -.06em;
      color: white;
    }.sc-tw .foot-copy{
      margin-top: 18px;
      max-width: 760px;
      color: rgba(255, 255, 255, .66);
      line-height: 1.95;
    }.sc-tw .foot-tags{
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      justify-content: flex-end;
    }.sc-tw .foot-tags span{
      padding: 12px 15px;
      background: rgba(255, 255, 255, .06);
      border: 1px solid rgba(255, 255, 255, .08);
      text-transform: uppercase;
      letter-spacing: .2em;
      font-size: 10px;
      color: rgba(255, 255, 255, .75);
    }.sc-tw .footer-line{
      margin: 34px 0;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .22), transparent);
    }.sc-tw .reveal{
      opacity: 0;
      transform: translateY(32px);
      transition: opacity .8s ease, transform .8s cubic-bezier(.16, 1, .3, 1);
    }.sc-tw .reveal.in{
      opacity: 1;
      transform: translateY(0);
    }

    @keyframes condense {to{
        opacity: 1;
        filter: blur(0);
        transform: translateY(0);
      }
    }

    @keyframes slatIn {to{
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes sheen {to{
        transform: translateX(240%) rotate(12deg);
      }
    }.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
      animation-duration: .72s;
      animation-timing-function: cubic-bezier(.16, 1, .3, 1);
    }

    @media (max-width: 1180px) {.sc-tw .header-rail{
        display: none;
      }.sc-tw .top-meter{
        right: 16px;
      }.sc-tw .hero-main{
        padding: 116px 20px 40px;
      }.sc-tw .sofa-split,.sc-tw .contrast-band,.sc-tw .foot-grid{
        grid-template-columns: 1fr;
      }.sc-tw .shelf-grid{
        display: grid;
        grid-template-columns: 1fr 1fr;
      }.sc-tw .shelf,.sc-tw .shelf.wide{
        grid-column: span 1;
      }.sc-tw .shelf.tall{
        min-height: 280px;
      }
    }

    @media (max-width: 760px) {.sc-tw .hero-title{
        font-size: clamp(4rem, 16vw, 7rem);
      }.sc-tw .hero-text{
        font-size: 15px;
      }.sc-tw .shell,.sc-tw .botanical-shell,.sc-tw .foot-shell{
        width: min(100% - 32px, 1480px);
      }.sc-tw .sofa-copy{
        padding: 34px;
      }.sc-tw .accent-pane{
        padding: 34px;
      }.sc-tw .shelf-grid{
        grid-template-columns: 1fr;
      }.sc-tw .foot{
